import{_ as a,o as r,c as e,ag as n}from"./chunks/framework.DXGyWiRo.js";const i="/assets/midnight_e45a4b16782a81e0b1714ece40c4c3c.JkS1Ondo.png",s="/assets/midnight_d7549bec2c0db7241d4aa2426bf8ff5.NxmmVL22.png",_=JSON.parse('{"title":"Midnight 使用教程","description":"","frontmatter":{},"headers":[],"relativePath":"cs2/midnight.md","filePath":"cs2/midnight.md"}'),o={name:"cs2/midnight.md"};function g(p,t,h,d,l,c){return r(),e("div",null,[...t[0]||(t[0]=[n('<h1 id="midnight-使用教程" tabindex="-1">Midnight 使用教程 <a class="header-anchor" href="#midnight-使用教程" aria-label="Permalink to &quot;Midnight 使用教程&quot;">​</a></h1><h2 id="注册" tabindex="-1">注册 <a class="header-anchor" href="#注册" aria-label="Permalink to &quot;注册&quot;">​</a></h2><p><strong>首先进入午夜注册官网 -&gt; <a href="https://midnight.im/join/93611/" target="_blank" rel="noreferrer">https://midnight.im/join/93611</a> -&gt; 右上角 Register（注册），如果已有账号点击 Log In 登陆即可。</strong></p><p><strong>注册时在弹出的窗口中 -&gt; 依次输入：用户名 / 邮箱 / 密码 / 完成人机验证 / 勾选协议 -&gt; 点击 Register 完成注册。</strong></p><h2 id="续费购买-激活卡密" tabindex="-1">续费购买 &amp; 激活卡密 <a class="header-anchor" href="#续费购买-激活卡密" aria-label="Permalink to &quot;续费购买 &amp; 激活卡密&quot;">​</a></h2><p><strong>续费就找卢姥爷，包你良好服务体验</strong></p><ol><li>您可以通过 <a href="https://midnight.im/usercp/" target="_blank" rel="noreferrer">https://midnight.im/usercp/</a> 或者导航栏中的 User CP 进入 Subscriptions 页面。</li><li>页面中右上角单击 <strong>ACTIVATE KEY（激活秘钥）</strong> -&gt; 在弹出的窗口中输入您购买的午夜秘钥 -&gt; <strong>ACTIVATE KEY</strong> 即可激活完毕。</li></ol><p>提示：您可以在此页面查看 HACK 过期时间。</p><h2 id="下载客户端" tabindex="-1">下载客户端 <a class="header-anchor" href="#下载客户端" aria-label="Permalink to &quot;下载客户端&quot;">​</a></h2><p>请通过论坛导航栏（论坛首页左上角）-&gt; <strong>DOWNLOAD LOADER（下载客户端）</strong> -&gt; 在弹出的页面中 -&gt; <strong>DOWNLOAD</strong> 即可下载客户端。</p><h2 id="注入" tabindex="-1">注入 <a class="header-anchor" href="#注入" aria-label="Permalink to &quot;注入&quot;">​</a></h2><p><strong>注意</strong>：注入前请先关闭你电脑中的全部杀毒软件（建议卸载火绒除外）和微软防火墙。读条长时间不动请挂梯子或者加速器。</p><p><strong>右键管理员身份运行午夜客户端文件</strong>（此步骤给予客户端可以注入进程相关权限避免无法注入）</p><p><img src="'+i+'" alt="登录界面"></p><p>输入您官网的邮箱与密码 -&gt; 单击 <strong>LOG IN NOW（现在登陆）</strong> -&gt; 此时会转圈加载然后查阅下一步</p><p><strong>选择 CSGO 版本 -&gt; START IT NOW（开始注入）</strong> / 本次选择 Beta 版注入游戏</p><p><img src="'+s+'" alt="注入选择"></p><p>单击完毕后 -&gt; 等待下载午夜客户端资源 -&gt; 开始转圈等待。（可能中途会弹 CMD 窗口无视即可）</p><p>注入过程中 -&gt; 绿色进度条 -&gt; 加载完毕会自动打开 Steam 平台 -&gt; 弹窗告知您可以运行 CSGO 客户端</p><p>最后运行 CSGO 游戏客户端进入大厅自动注入完毕 -&gt; 菜单自动呼出（INS 显示隐藏）-&gt; 享受游戏。</p>',20)])])}const f=a(o,[["render",g]]);export{_ as __pageData,f as default};
